parameters.pythonCode:
import json

# Get Gemini's response from the previous node
items = _items

result = []

for item in items:
    data = item["json"]

    try:
        # Gemini response
        candidates = data.get("candidates", [])

        if not candidates:
            raise ValueError("Gemini returned no candidates")

        parts = candidates[0]["content"]["parts"]

        response_text = ""

        for part in parts:
            if "text" in part:
                response_text += part["text"]

        # Convert Gemini JSON text into Python dictionary
        extracted = json.loads(response_text)

        # Standardize the final response
        final_data = {
            "success": True,
            "document_type": extracted.get(
                "document_type", "Unknown"
            ),
            "fields": extracted.get("fields", {}),
            "notes": extracted.get("notes", "")
        }

        result.append({
            "json": final_data
        })

    except Exception as error:
        result.append({
            "json": {
                "success": False,
                "error": str(error),
                "document_type": None,
                "fields": {},
                "notes": "Could not extract information"
            }
        })

return result
